'use strict';
(()=>{const q=new URLSearchParams(location.search),en=q.get('language')==='en',paper=['A4','A5','Letter'].includes(q.get('paper'))?q.get('paper'):'A4',orientation=q.get('orientation')==='landscape'?'landscape':'portrait',set=(id,text)=>{document.getElementById(id).textContent=text;};document.documentElement.lang=en?'en':'zh-CN';document.body.className=paper+'-'+orientation;set('title',en?'Printer Test Page':'打印测试页');set('queue-label',en?'System Queue':'系统队列');set('paper-label',en?'Paper / Orientation':'纸张 / 方向');set('time-label',en?'Time':'时间');set('queue',(q.get('queue')||'—').slice(0,240));set('paper',paper+' / '+(en?orientation:orientation==='portrait'?'纵向':'横向'));set('time',(q.get('at')||'—').slice(0,80));set('notice',en?'Select the specified queue in the system print dialog, then verify orientation and paper output.':'请在系统打印窗口选择指定队列，核对纸张方向与实际出纸。');set('print',en?'Open Print Dialog':'打开打印窗口');set('result',en?'This page does not record verified physical paper output.':'本页不记录实体出纸成功状态。');document.getElementById('print').onclick=()=>window.print();})();
